<?php require_once __DIR__.'/bootstrap.php';require_login();$title='History — AniRead';include __DIR__.'/includes/header.php';?><h1>Watch history</h1><table class="table"><tr><th>Anime</th><th>Episode</th><th>Last watched</th></tr><?php $s=$pdo->prepare('SELECT a.id,a.title,h.episode_number,h.updated_at FROM watch_history h JOIN anime a ON a.id=h.anime_id WHERE h.user_id=? ORDER BY h.updated_at DESC');$s->execute([user()['id']]);foreach($s as $h):?><tr><td><a href="anime.php?id=<?=$h['id']?>"><?=e($h['title'])?></a></td><td><a href="watch.php?id=<?=$h['id']?>&episode=<?=$h['episode_number']?>">Episode <?=$h['episode_number']?></a></td><td><?=e($h['updated_at'])?></td></tr><?php endforeach;?></table><?php include __DIR__.'/includes/footer.php';
